INSERT INTO formations (id, title, formation_type, primary_virtue, description, liturgical_script, context_anchor, min_age_months, max_age_months) VALUES
('verse_week_01', 'Week 1: Creation', 'liturgy', 'Wonder', 'Genesis 1:1', 'In the beginning, God created the heavens and the earth.', 'Morning_Circle', 48, 216),
('verse_week_02', 'Week 2: Image of God', 'liturgy', 'Identity', 'Genesis 1:27', 'So God created man in his own image, in the image of God created he him; male and female created he them.', 'Morning_Circle', 48, 216),
('verse_week_03', 'Week 3: The Promise', 'liturgy', 'Hope', 'Genesis 3:15', 'And I will put enmity between thee and the woman, and between thy seed and her seed; it shall bruise thy head, and thou shalt bruise his heel.', 'Morning_Circle', 48, 216),
('verse_week_04', 'Week 4: The Covenant', 'liturgy', 'Faithfulness', 'Genesis 9:13', 'I do set my bow in the cloud, and it shall be for a token of a covenant between me and the earth.', 'Morning_Circle', 48, 216),
('verse_week_05', 'Week 5: The Call', 'liturgy', 'Faith', 'Genesis 12:3', 'And I will bless them that bless thee, and curse him that curseth thee: and in thee shall all families of the earth be blessed.', 'Morning_Circle', 48, 216),
('verse_week_06', 'Week 6: Providence', 'liturgy', 'Trust', 'Genesis 50:20', 'But as for you, ye thought evil against me; but God meant it unto good, to bring to pass, as it is this day, to save much people alive.', 'Morning_Circle', 48, 216),
('verse_week_07', 'Week 7: The Name', 'liturgy', 'Awe', 'Exodus 3:14', 'And God said unto Moses, I AM THAT I AM: and he said, Thus shalt thou say unto the children of Israel, I AM hath sent me unto you.', 'Morning_Circle', 48, 216),
('verse_week_08', 'Week 8: Deliverance', 'liturgy', 'Salvation', 'Exodus 14:14', 'The LORD shall fight for you, and ye shall hold your peace.', 'Morning_Circle', 48, 216),
('verse_week_09', 'Week 9: No Other Gods', 'liturgy', 'Worship', 'Exodus 20:3', 'Thou shalt have no other gods before me.', 'Morning_Circle', 48, 216),
('verse_week_10', 'Week 10: Holiness', 'liturgy', 'Holiness', 'Leviticus 19:2', 'Speak unto all the congregation of the children of Israel, and say unto them, Ye shall be holy: for I the LORD your God am holy.', 'Morning_Circle', 48, 216),
('verse_week_11', 'Week 11: The Blessing', 'liturgy', 'Peace', 'Numbers 6:24-26', 'The LORD bless thee, and keep thee: The LORD make his face shine upon thee, and be gracious unto thee: The LORD lift up his countenance upon thee, and give thee peace.', 'Morning_Circle', 48, 216),
('verse_week_12', 'Week 12: Obedience', 'liturgy', 'Obedience', 'Deuteronomy 5:33', 'Ye shall walk in all the ways which the LORD your God hath commanded you, that ye may live, and that it may be well with you.', 'Morning_Circle', 48, 216),
('verse_week_13', 'Week 13: The Great Commandment', 'liturgy', 'Love', 'Deuteronomy 6:5', 'And thou shalt love the LORD thy God with all thine heart, and with all thy soul, and with all thy might.', 'Morning_Circle', 48, 216),

-- Weeks 14-26: Kingdom, Wisdom, Prophets (Josh - Mal)
('verse_week_14', 'Week 14: Courage', 'liturgy', 'Courage', 'Joshua 1:9', 'Have not I commanded thee? Be strong and of a good courage; be not afraid, neither be thou dismayed: for the LORD thy God is with thee whithersoever thou goest.', 'Morning_Circle', 48, 216),
('verse_week_15', 'Week 15: Loyalty', 'liturgy', 'Loyalty', 'Ruth 1:16', 'And Ruth said, Intreat me not to leave thee, or to return from following after thee: for whither thou goest, I will go; and where thou lodgest, I will lodge: thy people shall be my people, and thy God my God.', 'Morning_Circle', 48, 216),
('verse_week_16', 'Week 16: The Heart', 'liturgy', 'Humility', '1 Samuel 16:7', 'For the LORD seeth not as man seeth; for man looketh on the outward appearance, but the LORD looketh on the heart.', 'Morning_Circle', 48, 216),
('verse_week_17', 'Week 17: God''s Greatness', 'liturgy', 'Reverence', '2 Samuel 7:22', 'Wherefore thou art great, O LORD God: for there is none like thee, neither is there any God beside thee, according to all that we have heard with our ears.', 'Morning_Circle', 48, 216),
('verse_week_18', 'Week 18: God Alone', 'liturgy', 'Truth', '1 Kings 8:60', 'That all the people of the earth may know that the LORD is God, and that there is none else.', 'Morning_Circle', 48, 216),
('verse_week_19', 'Week 19: The Joy of the Lord', 'liturgy', 'Joy', 'Nehemiah 8:10', 'Then he said unto them, Go your way, eat the fat, and drink the sweet, and send portions unto them for whom nothing is prepared: for this day is holy unto our Lord: neither be ye sorry; for the joy of the LORD is your strength.', 'Morning_Circle', 48, 216),
('verse_week_20', 'Week 20: The Redeemer', 'liturgy', 'Hope', 'Job 19:25', 'For I know that my redeemer liveth, and that he shall stand at the latter day upon the earth.', 'Morning_Circle', 48, 216),
('verse_week_21', 'Week 21: God''s Glory', 'liturgy', 'Wonder', 'Psalm 19:1', 'The heavens declare the glory of God; and the firmament sheweth his handywork.', 'Morning_Circle', 48, 216),
('verse_week_22', 'Week 22: The Shepherd', 'liturgy', 'Comfort', 'Psalm 23:1', 'The LORD is my shepherd; I shall not want.', 'Morning_Circle', 48, 216),
('verse_week_23', 'Week 23: God''s Word', 'liturgy', 'Wisdom', 'Psalm 119:105', 'Thy word is a lamp unto my feet, and a light unto my path.', 'Morning_Circle', 48, 216),
('verse_week_24', 'Week 24: Trust in the Lord', 'liturgy', 'Trust', 'Proverbs 3:5-6', 'Trust in the LORD with all thine heart; and lean not unto thine own understanding. In all thy ways acknowledge him, and he shall direct thy paths.', 'Morning_Circle', 48, 216),
('verse_week_25', 'Week 25: The Messiah', 'liturgy', 'Peace', 'Isaiah 9:6', 'For unto us a child is born, unto us a son is given: and the government shall be upon his shoulder: and his name shall be called Wonderful, Counsellor, The mighty God, The everlasting Father, The Prince of Peace.', 'Morning_Circle', 48, 216),
('verse_week_26', 'Week 26: What God Requires', 'liturgy', 'Justice', 'Micah 6:8', 'He hath shewed thee, O man, what is good; and what doth the LORD require of thee, but to do justly, and to love mercy, and to walk humbly with thy God?', 'Morning_Circle', 48, 216),

-- Weeks 27-39: Gospels & Acts (Jesus'' Life & Early Church)
('verse_week_27', 'Week 27: Jesus Saves', 'liturgy', 'Salvation', 'Matthew 1:21', 'And she shall bring forth a son, and thou shalt call his name JESUS: for he shall save his people from their sins.', 'Morning_Circle', 48, 216),
('verse_week_28', 'Week 28: Good Tidings', 'liturgy', 'Joy', 'Luke 2:10-11', 'And the angel said unto them, Fear not: for, behold, I bring you good tidings of great joy, which shall be to all people. For unto you is born this day in the city of David a Saviour, which is Christ the Lord.', 'Morning_Circle', 48, 216),
('verse_week_29', 'Week 29: The Word Made Flesh', 'liturgy', 'Truth', 'John 1:14', 'And the Word was made flesh, and dwelt among us, (and we beheld his glory, the glory as of the only begotten of the Father,) full of grace and truth.', 'Morning_Circle', 48, 216),
('verse_week_30', 'Week 30: The Kingdom', 'liturgy', 'Repentance', 'Mark 1:15', 'The time is fulfilled, and the kingdom of God is at hand: repent ye, and believe the gospel.', 'Morning_Circle', 48, 216),
('verse_week_31', 'Week 31: Light of the World', 'liturgy', 'Purpose', 'Matthew 5:16', 'Let your light so shine before men, that they may see your good works, and glorify your Father which is in heaven.', 'Morning_Circle', 48, 216),
('verse_week_32', 'Week 32: Rest', 'liturgy', 'Rest', 'Matthew 11:28', 'Come unto me, all ye that labour and are heavy laden, and I will give you rest.', 'Morning_Circle', 48, 216),
('verse_week_33', 'Week 33: A Ransom for Many', 'liturgy', 'Service', 'Mark 10:45', 'For even the Son of man came not to be ministered unto, but to minister, and to give his life a ransom for many.', 'Morning_Circle', 48, 216),
('verse_week_34', 'Week 34: Seek and Save', 'liturgy', 'Compassion', 'Luke 19:10', 'For the Son of man is come to seek and to save that which was lost.', 'Morning_Circle', 48, 216),
('verse_week_35', 'Week 35: God So Loved', 'liturgy', 'Love', 'John 3:16', 'For God so loved the world, that he gave his only begotten Son, that whosoever believeth in him should not perish, but have everlasting life.', 'Morning_Circle', 48, 216),
('verse_week_36', 'Week 36: The Way', 'liturgy', 'Truth', 'John 14:6', 'Jesus saith unto him, I am the way, the truth, and the life: no man cometh unto the Father, but by me.', 'Morning_Circle', 48, 216),
('verse_week_37', 'Week 37: The Great Commission', 'liturgy', 'Mission', 'Matthew 28:19-20', 'Go ye therefore, and teach all nations, baptizing them in the name of the Father, and of the Son, and of the Holy Ghost: Teaching them to observe all things whatsoever I have commanded you: and, lo, I am with you alway, even unto the end of the world. Amen.', 'Morning_Circle', 48, 216),
('verse_week_38', 'Week 38: Resurrection Power', 'liturgy', 'Power', 'John 11:25', 'Jesus said unto her, I am the resurrection, and the life: he that believeth in me, though he were dead, yet shall he live.', 'Morning_Circle', 48, 216),
('verse_week_39', 'Week 39: Witnesses', 'liturgy', 'Courage', 'Acts 1:8', 'But ye shall receive power, after that the Holy Ghost is come upon you: and ye shall be witnesses unto me both in Jerusalem, and in all Judaea, and in Samaria, and unto the uttermost part of the earth.', 'Morning_Circle', 48, 216),

-- Weeks 40-52: Epistles & Revelation (Doctrine & Hope)
('verse_week_40', 'Week 40: Power of the Gospel', 'liturgy', 'Faith', 'Romans 1:16', 'For I am not ashamed of the gospel of Christ: for it is the power of God unto salvation to every one that believeth; to the Jew first, and also to the Greek.', 'Morning_Circle', 48, 216),
('verse_week_41', 'Week 41: Justified by Grace', 'liturgy', 'Grace', 'Romans 3:23-24', 'For all have sinned, and come short of the glory of God; Being justified freely by his grace through the redemption that is in Christ Jesus.', 'Morning_Circle', 48, 216),
('verse_week_42', 'Week 42: No Condemnation', 'liturgy', 'Freedom', 'Romans 8:1', 'There is therefore now no condemnation to them which are in Christ Jesus, who walk not after the flesh, but after the Spirit.', 'Morning_Circle', 48, 216),
('verse_week_43', 'Week 43: New Creation', 'liturgy', 'Transformation', '2 Corinthians 5:17', 'Therefore if any man be in Christ, he is a new creature: old things are passed away; behold, all things are become new.', 'Morning_Circle', 48, 216),
('verse_week_44', 'Week 44: Fruit of the Spirit', 'liturgy', 'Self-Control', 'Galatians 5:22-23', 'But the fruit of the Spirit is love, joy, peace, longsuffering, gentleness, goodness, faith, Meekness, temperance: against such there is no law.', 'Morning_Circle', 48, 216),
('verse_week_45', 'Week 45: Saved by Grace', 'liturgy', 'Humility', 'Ephesians 2:8-9', 'For by grace are ye saved through faith; and that not of yourselves: it is the gift of God: Not of works, lest any man should boast.', 'Morning_Circle', 48, 216),
('verse_week_46', 'Week 46: The Fullness of God', 'liturgy', 'Supremacy', 'Colossians 1:16-17', 'For by him were all things created, that are in heaven, and that are in earth... and he is before all things, and by him all things consist.', 'Morning_Circle', 48, 216),
('verse_week_47', 'Week 47: Work as Worship', 'liturgy', 'Diligence', 'Colossians 3:23', 'And whatsoever ye do, do it heartily, as to the Lord, and not unto men.', 'Morning_Circle', 48, 216),
('verse_week_48', 'Week 48: Rejoice Always', 'liturgy', 'Joy', 'Philippians 4:4', 'Rejoice in the Lord alway: and again I say, Rejoice.', 'Morning_Circle', 48, 216),
('verse_week_49', 'Week 49: God-Breathed', 'liturgy', 'Wisdom', '2 Timothy 3:16', 'All scripture is given by inspiration of God, and is profitable for doctrine, for reproof, for correction, for instruction in righteousness.', 'Morning_Circle', 48, 216),
('verse_week_50', 'Week 50: Faith', 'liturgy', 'Faith', 'Hebrews 11:1', 'Now faith is the substance of things hoped for, the evidence of things not seen.', 'Morning_Circle', 48, 216),
('verse_week_51', 'Week 51: Love One Another', 'liturgy', 'Love', '1 John 4:19', 'We love him, because he first loved us.', 'Morning_Circle', 48, 216),
('verse_week_52', 'Week 52: All Things New', 'liturgy', 'Hope', 'Revelation 21:4', 'And God shall wipe away all tears from their eyes; and there shall be no more death, neither sorrow, nor crying, neither shall there be any more pain: for the former things are passed away.', 'Morning_Circle', 48, 216);
